mapper.select:
SELECT c.id AS "id", c.client_code AS "clientCode", c.name AS "name"
  FROM clients c
 WHERE c.client_code = #{clientCode}

SELECT r.id AS "id", r.status AS "status", r.doc_date AS "docDate"
  FROM qdoc_record r
 WHERE r.form_id = #{formId}
   AND COALESCE(r.bind_id, 0) = #{bindId}
   AND r.doc_date BETWEEN #{start} AND #{end}
 ORDER BY r.id DESC
 LIMIT 1

SELECT r.id AS "id", r.status AS "status", r.doc_date AS "docDate"
  FROM qdoc_record r
 WHERE r.form_id = #{formId}
   AND COALESCE(r.bind_id, 0) = #{bindId}
   AND r.doc_date = #{docDate}
 ORDER BY r.id DESC
 LIMIT 1

SELECT FROM qdoc_record r
WHERE 1 = 1
AND r.doc_date BETWEEN #{start} AND #{end}
AND r.form_id = #{formId}
ORDER BY r.doc_date DESC, r.id DESC LIMIT 300

SELECT a.record_id AS "recordId", a.item_id AS "itemId", a.value_text AS "valueText", a.note AS "note", a.defect AS "defect"
  FROM qdoc_answer a
 WHERE a.record_id = #{recordId}
